import{_ as i,l as n,o as e,c as o,v as t,p as s,x as r,d,i as p,S as E}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"学习索引","description":"","frontmatter":{"title":"学习索引","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/learned-index.md","filePath":"cs/learned-index.md","lastUpdated":1789023840000}'),c={name:"cs/learned-index.md"};function h(A,a,_,B,m,D){const l=n("Mermaid");return e(),o("div",null,[a[1]||(a[1]=t('<h1 id="学习索引" tabindex="-1">学习索引 <a class="header-anchor" href="#学习索引" aria-label="Permalink to &quot;学习索引&quot;">​</a></h1><div class="epigraph"><p>把有序键到位置看成回归：模型预测页号，再局部纠正。分布稳定时少一层指针，分布一漂就变成错页扫描。</p><footer>—— 据 Kraska et al., The Case for Learned Index Structures, SIGMOD 2018；B+ 对照</footer></div><p><a href="/cs/spatial-index-db">上一课</a>的键没有全序友好。本课回到一维有序键。缺口是：B+ 用内部节点存分隔键；若键分布可用函数逼近，模型可预测叶位置，内部节点缩小或消失。学习索引（learned index）是存储结构上的模型，与学习型优化器（选计划）不是同一插件。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>静态有序数组上，CDF 模型预测 rank，误差界限内二分纠正。动态插入：要增量训练或混合结构（RMI + 缓冲树）。缺口是<strong>工作负载假设</strong>：只读或追加、键分布缓变。OLTP 随机插入、删除空洞，模型过期则预测偏差大，最坏退化成大范围扫描——比 B+ 最坏对数更差。</p><p>与 ART/Bw：那些是精确结构。学习索引用近似+纠正。事务、并发、恢复都要定义「模型版本」与页一致性。</p><p><span class="marginnote">Kraska et al. SIGMOD 2018。后续有动态学习索引。本课不把神经网络当 B+ 的默认替换。无虚构编号。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>训练：用键与位置拟合分段线性或小网络。查询：预测 → 在误差半径内搜。更新：缓冲新键，定期重训练，或把学习索引当只读段（LSM 里对 SST 建模型，不可变正好）。</p><p>优化器：代价按预测误差半径的期望探测次数，需校准。</p>',10)),(e(),s(E,null,{default:r(()=>[p(l,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20KEY%5B%22%E6%9C%89%E5%BA%8F%E9%94%AE%22%5D%20--%3E%20MOD%5B%22CDF%20%2F%20%E5%88%86%E6%AE%B5%E6%A8%A1%E5%9E%8B%22%5D%0A%20%20MOD%20--%3E%20POS%5B%22%E9%A2%84%E6%B5%8B%E4%BD%8D%E7%BD%AE%22%5D%0A%20%20POS%20--%3E%20FIX%5B%22%E8%AF%AF%E5%B7%AE%E5%8D%8A%E5%BE%84%E5%86%85%E7%BA%A0%E6%AD%A3%22%5D%0A%20%20UPD%5B%22%E6%8F%92%E5%85%A5%22%5D%20--%3E%20RET%5B%22%E7%BC%93%E5%86%B2%E6%88%96%E9%87%8D%E8%AE%AD%E7%BB%83%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>LSM+学习：对每个不可变 SST 训一个小模型，compaction 后重训，避开动态问题。B+ 内部页减少缓存占用，是论文卖点；要对比 ART 的前缀压缩是否已经够。</p><p>正确性：纠正步骤必须找到真键或证明不存在，不能只信模型。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲变长溢出页。也不把学习索引用于空间 MBR（研究有，主干不依赖）。字符串键、多列组合键的模型更脆。</p><p>后课默认：学习索引适合只读或 LSM 段上的有序点查；OLTP 默认精确树。变长记录与溢出页：行存页装不下时的经典问题，与模型无关。</p><p>近似结构必须有精确收尾，否则隔离与约束都无法谈。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>学习索引回归键到位置，再用局部搜索纠正。</li><li>动态更新与分布漂移是硬边界；LSM 段上更自然。</li><li>变长记录与溢出页下一课：行在页里如何拆。</li><li>出处：Kraska et al. SIGMOD 2018；B+ / ART 对照。</li></ul>',9))])}const T=i(c,[["render",h]]);export{S as __pageData,T as default};
